"use client";

import React, { useState, useMemo, useEffect } from "react";
import { 
  ChevronLeft, ChevronRight, Plus, Trash2, Copy, 
  Check, Save, Wand2, Calendar, Lock, Palmtree, 
  AlertTriangle, X, History, Clock, MoreHorizontal,
  PieChart, ArrowRight, Loader2, RefreshCw
} from "lucide-react";

/* ---------------- 1. CONFIGURATION ---------------- */
const HOLIDAYS = ["2026-01-26"]; 
const APPROVED_LEAVES = ["2026-01-27"]; 

const PROJECTS = [
    { id: "p1", name: "Internal / Admin", code: "INT-001", color: "bg-slate-500", billable: false },
    { id: "p2", name: "Acme Corp: Redesign", code: "ACM-102", color: "bg-blue-600", billable: true },
    { id: "p3", name: "Globex: Mobile App", code: "GLO-404", color: "bg-indigo-600", billable: true },
    { id: "p4", name: "Stark Ind: Consulting", code: "STK-999", color: "bg-amber-600", billable: true },
];

/* ---------------- 2. TYPES ---------------- */
type Status = "DRAFT" | "SUBMITTED" | "APPROVED";

interface DayEntry {
    id: string;
    projectId: string;
    hours: number;
    minutes: number;
    notes: string;
}

interface WeekData {
    status: Status;
    lastSaved: Date | null;
    entries: Record<string, DayEntry[]>;
}

type TimesheetDB = Record<string, WeekData>;

/* ---------------- 3. HELPERS ---------------- */
const formatDate = (d: Date) => d.toISOString().split("T")[0];
const addDays = (d: Date, days: number) => {
    const nd = new Date(d);
    nd.setDate(nd.getDate() + days);
    return nd;
};
const startOfWeek = (date: Date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    d.setHours(0, 0, 0, 0);
    return d;
};
const formatDuration = (h: number, m: number) => {
    if (h === 0 && m === 0) return "0h";
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
};

/* ---------------- 4. MAIN COMPONENT ---------------- */
export default function RobustTimesheet() {
    // State
    const [currentWeekStart, setCurrentWeekStart] = useState<Date>(startOfWeek(new Date("2026-01-26")));
    const [db, setDb] = useState<TimesheetDB>({
        "2026-01-26": { status: "DRAFT", lastSaved: null, entries: {} }
    });

    // UI State
    const [selectedDate, setSelectedDate] = useState<string | null>(null); 
    const [isCopyMenuOpen, setIsCopyMenuOpen] = useState(false);
    const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
    const [toast, setToast] = useState<{ type: 'success' | 'error', msg: string } | null>(null);

    // Helpers
    const currentWeekKey = formatDate(currentWeekStart);
    const currentData = db[currentWeekKey] || { status: "DRAFT", lastSaved: null, entries: {} };
    const isLocked = currentData.status !== "DRAFT";

    // Auto-dismiss toast
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    /* --- DERIVED: DAYS --- */
    const days = useMemo(() => {
        return Array.from({ length: 7 }).map((_, i) => {
            const d = addDays(currentWeekStart, i);
            const dateStr = formatDate(d);
            const isBlocked = HOLIDAYS.includes(dateStr) || APPROVED_LEAVES.includes(dateStr);

            return {
                label: d.toLocaleDateString("en-US", { weekday: "short" }),
                fullLabel: d.toLocaleDateString("en-US", { weekday: "long", month: 'short', day: 'numeric' }),
                date: dateStr,
                dayNum: d.getDate(),
                isWeekend: i === 5 || i === 6,
                isBlocked,
                isHoliday: HOLIDAYS.includes(dateStr),
                isLeave: APPROVED_LEAVES.includes(dateStr),
                entries: currentData.entries[dateStr] || []
            };
        });
    }, [currentWeekStart, currentData]);

    /* --- DERIVED: STATS & PROJECT SUMMARY --- */
    const { stats, projectSummary } = useMemo(() => {
        let totalMins = 0;
        let billableMins = 0;
        const summary: Record<string, number> = {};

        Object.values(currentData.entries).forEach(dayEntries => {
            dayEntries.forEach(e => {
                const mins = (e.hours * 60) + e.minutes;
                totalMins += mins;
                if (PROJECTS.find(p => p.id === e.projectId)?.billable) billableMins += mins;
                
                // Project Summary
                summary[e.projectId] = (summary[e.projectId] || 0) + mins;
            });
        });

        return { 
            stats: { 
                total: (totalMins / 60).toFixed(1), 
                billable: (billableMins / 60).toFixed(1), 
                utilization: Math.min(100, (totalMins / 2400) * 100) // Based on 40h (2400m)
            },
            projectSummary: summary
        };
    }, [currentData]);

    /* --- ACTIONS --- */
    const updateDb = (fn: (prev: TimesheetDB) => TimesheetDB) => {
        setDb(prev => fn(prev));
        if (!isLocked) setHasUnsavedChanges(true);
    };

    const handleNavigate = (dir: 'prev' | 'next') => {
        if (hasUnsavedChanges && !confirm("You have unsaved changes. Navigate anyway?")) return;
        setCurrentWeekStart(prev => addDays(prev, dir === 'next' ? 7 : -7));
        setHasUnsavedChanges(false);
    };

    /* --- FEATURE: SAVE DRAFT --- */
    const handleSaveDraft = () => {
        setIsSaving(true);
        // Simulate network delay
        setTimeout(() => {
            updateDb(prev => ({
                ...prev,
                [currentWeekKey]: { ...currentData, lastSaved: new Date() }
            }));
            setIsSaving(false);
            setHasUnsavedChanges(false);
            setToast({ type: 'success', msg: "Draft saved successfully" });
        }, 800);
    };

    /* --- FEATURE: SMART ACTIONS --- */
    const handleSmartFill = () => {
        if (isLocked) return;
        const newEntries = { ...currentData.entries };
        let count = 0;

        days.slice(0, 5).forEach(d => {
            if (d.isBlocked) return;
            if (!newEntries[d.date] || newEntries[d.date].length === 0) {
                newEntries[d.date] = [{
                    id: crypto.randomUUID(),
                    projectId: PROJECTS[0].id,
                    hours: 8,
                    minutes: 0,
                    notes: "Standard Hours"
                }];
                count++;
            }
        });

        updateDb(prev => ({ ...prev, [currentWeekKey]: { ...currentData, entries: newEntries } }));
        setToast({ type: 'success', msg: `Auto-filled ${count} days` });
    };

    const handleCopyDayToNext = (dateStr: string) => {
        const sourceEntries = currentData.entries[dateStr] || [];
        if (sourceEntries.length === 0) return;

        const nextDay = addDays(new Date(dateStr), 1);
        const nextDayStr = formatDate(nextDay);
        
        // Don't overwrite if blocked or outside current week view (simple logic for now)
        if (HOLIDAYS.includes(nextDayStr) || APPROVED_LEAVES.includes(nextDayStr)) {
            setToast({ type: 'error', msg: "Cannot copy to a blocked day" });
            return;
        }

        const newEntries = sourceEntries.map(e => ({ ...e, id: crypto.randomUUID() }));
        
        updateDb(prev => {
            const week = prev[currentWeekKey];
            return {
                ...prev,
                [currentWeekKey]: {
                    ...week,
                    entries: { ...week.entries, [nextDayStr]: [...(week.entries[nextDayStr] || []), ...newEntries] }
                }
            };
        });
        setToast({ type: 'success', msg: "Copied to next day" });
    };

    const handleClearDay = (dateStr: string) => {
        if (confirm("Clear all entries for this day?")) {
            updateDb(prev => {
                const week = prev[currentWeekKey];
                const newEntries = { ...week.entries };
                delete newEntries[dateStr];
                return { ...prev, [currentWeekKey]: { ...week, entries: newEntries } };
            });
        }
    };

    const handleSubmit = () => {
        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, status: "SUBMITTED" }
        }));
        setIsSubmitModalOpen(false);
        setHasUnsavedChanges(false);
        setToast({ type: 'success', msg: "Timesheet Submitted!" });
    };

    /* --- SIDE PANEL ACTIONS --- */
    const addEntry = (date: string) => {
        const newEntry = { id: crypto.randomUUID(), projectId: PROJECTS[0].id, hours: 0, minutes: 0, notes: "" };
        updateDb(prev => {
            const week = prev[currentWeekKey] || { status: 'DRAFT', entries: {} };
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: [...(week.entries[date] || []), newEntry] } } };
        });
    };

    const updateEntry = (date: string, id: string, field: keyof DayEntry, val: any) => {
        let cleanVal = val;
        if (field === 'hours') cleanVal = Math.max(0, parseInt(val) || 0);
        if (field === 'minutes') cleanVal = Math.max(0, Math.min(59, parseInt(val) || 0));

        updateDb(prev => {
            const week = prev[currentWeekKey];
            const updated = week.entries[date].map(e => e.id === id ? { ...e, [field]: cleanVal } : e);
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: updated } } };
        });
    };

    const deleteEntry = (date: string, id: string) => {
        updateDb(prev => {
            const week = prev[currentWeekKey];
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: week.entries[date].filter(e => e.id !== id) } } };
        });
    };

    return (
        <div className="min-h-screen bg-[#F8F9FC] dark:bg-[#0B0F19] text-slate-900 dark:text-slate-100 font-sans pb-32">
            
            {/* 1. HEADER */}
            <div className="bg-white dark:bg-[#11151F] border-b border-slate-200 dark:border-slate-800 px-6 py-4 sticky top-0 z-30">
                <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-600 text-white rounded-lg"><Clock size={20} /></div>
                        <div>
                            <h1 className="text-lg font-bold leading-none">Timesheet</h1>
                            <div className="flex items-center gap-2 mt-1">
                                <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${currentData.status === 'DRAFT' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                                    {currentData.status}
                                </span>
                                {currentData.lastSaved && <span className="text-xs text-slate-400">Saved {currentData.lastSaved.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>}
                            </div>
                        </div>
                    </div>

                    {/* Week Navigation */}
                    <div className="flex items-center bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                        <button onClick={() => handleNavigate('prev')} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-md shadow-sm transition-all"><ChevronLeft size={16}/></button>
                        <div className="px-6 text-center">
                            <span className="text-[10px] font-bold text-slate-400 uppercase block">Week of</span>
                            <span className="text-xs font-bold tabular-nums">{days[0].date}</span>
                        </div>
                        <button onClick={() => handleNavigate('next')} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-md shadow-sm transition-all"><ChevronRight size={16}/></button>
                    </div>
                </div>
            </div>

            {/* 2. DASHBOARD WIDGETS */}
            <div className="max-w-7xl mx-auto px-6 py-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
                
                {/* Stats Widget */}
                <div className="bg-white dark:bg-[#11151F] rounded-2xl border border-slate-200 dark:border-slate-800 p-5 shadow-sm">
                    <div className="flex justify-between items-start mb-4">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Total Utilization</h3>
                        <PieChart size={16} className="text-slate-400" />
                    </div>
                    <div className="flex items-end gap-2 mb-2">
                        <span className="text-4xl font-black text-slate-900 dark:text-white">{stats.total}</span>
                        <span className="text-lg font-bold text-slate-400 mb-1">/ 40h</span>
                    </div>
                    <div className="h-2 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                        <div className={`h-full transition-all duration-1000 ${stats.utilization > 100 ? 'bg-red-500' : 'bg-blue-600'}`} style={{ width: `${stats.utilization}%` }} />
                    </div>
                </div>

                {/* Project Breakdown */}
                <div className="lg:col-span-2 bg-white dark:bg-[#11151F] rounded-2xl border border-slate-200 dark:border-slate-800 p-5 shadow-sm overflow-hidden">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Weekly Breakdown</h3>
                    <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-none">
                        {PROJECTS.map(p => {
                            const mins = projectSummary[p.id] || 0;
                            const hours = (mins / 60).toFixed(1);
                            if (mins === 0) return null;
                            return (
                                <div key={p.id} className="flex-shrink-0 bg-slate-50 dark:bg-slate-900 rounded-xl p-3 border border-slate-100 dark:border-slate-800 min-w-[140px]">
                                    <div className="flex items-center gap-2 mb-2">
                                        <div className={`w-2 h-2 rounded-full ${p.color}`} />
                                        <span className="text-[10px] font-bold text-slate-500 truncate">{p.code}</span>
                                    </div>
                                    <div className="text-lg font-bold text-slate-800 dark:text-slate-200">{hours}h</div>
                                    <div className="text-[10px] text-slate-400 truncate max-w-[120px]">{p.name}</div>
                                </div>
                            )
                        })}
                        {Object.keys(projectSummary).length === 0 && (
                            <div className="text-xs text-slate-400 italic">No hours logged yet.</div>
                        )}
                    </div>
                </div>
            </div>

            {/* 3. TOOLBAR */}
            <div className="max-w-7xl mx-auto px-6 mb-6 flex justify-end gap-3">
                <button onClick={handleSmartFill} disabled={isLocked} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg text-xs font-bold text-slate-600 dark:text-slate-300 hover:border-purple-500 transition-all shadow-sm disabled:opacity-50">
                    <Wand2 size={16} className="text-purple-500" /> Smart Fill
                </button>
            </div>

            {/* 4. GRID */}
            <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 md:grid-cols-7 gap-4">
                {days.map((d) => {
                    const totalMins = d.entries.reduce((a, b) => a + (b.hours * 60) + b.minutes, 0);
                    const totalHours = Math.floor(totalMins / 60);
                    const totalMinutes = totalMins % 60;
                    
                    return (
                        <div 
                            key={d.date}
                            className={`
                                relative min-h-[240px] rounded-2xl border transition-all duration-300 flex flex-col group
                                ${d.isBlocked 
                                    ? "bg-slate-50 dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 cursor-not-allowed" 
                                    : "bg-white dark:bg-[#11151F] border-slate-200 dark:border-slate-800 hover:border-blue-400 hover:shadow-lg"
                                }
                            `}
                        >
                            {/* Card Header */}
                            <div className="p-3 border-b border-slate-100 dark:border-slate-800/50 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/30 rounded-t-2xl">
                                <div>
                                    <div className="text-[10px] font-black uppercase text-slate-400">{d.label}</div>
                                    <div className={`text-xl font-black ${d.isBlocked ? 'text-slate-300' : 'text-slate-800 dark:text-white'}`}>{d.dayNum}</div>
                                </div>
                                {d.isHoliday && <Lock size={16} className="text-purple-400" />}
                                {d.isLeave && <Palmtree size={16} className="text-amber-400" />}
                                {!d.isBlocked && totalMins > 0 && (
                                    <span className="text-[10px] font-black px-2 py-0.5 rounded bg-slate-100 text-slate-600">
                                        {formatDuration(totalHours, totalMinutes)}
                                    </span>
                                )}
                            </div>

                            {/* Entries Area */}
                            <div 
                                onClick={() => !d.isBlocked && !isLocked && setSelectedDate(d.date)}
                                className={`flex-1 p-2 space-y-2 overflow-y-auto max-h-[300px] custom-scrollbar ${!d.isBlocked && !isLocked ? 'cursor-pointer' : ''}`}
                            >
                                {d.entries.map(e => {
                                    const proj = PROJECTS.find(p => p.id === e.projectId);
                                    return (
                                        <div key={e.id} className="p-2 bg-white dark:bg-slate-900 rounded-lg border border-slate-100 dark:border-slate-800 shadow-sm">
                                            <div className="flex justify-between mb-1">
                                                <div className={`w-1.5 h-1.5 rounded-full ${proj?.color}`} />
                                                <span className="text-[10px] font-bold">{formatDuration(e.hours, e.minutes)}</span>
                                            </div>
                                            <p className="text-[10px] text-slate-500 font-medium truncate">{proj?.code}</p>
                                        </div>
                                    )
                                })}
                                
                                {!d.isBlocked && d.entries.length === 0 && (
                                    <div className="h-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                        <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-500 flex items-center justify-center">
                                            <Plus size={16} />
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Card Footer Actions */}
                            {!isLocked && !d.isBlocked && (
                                <div className="p-2 border-t border-slate-100 dark:border-slate-800 flex justify-between opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={(e) => { e.stopPropagation(); handleClearDay(d.date); }} className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-md transition-colors" title="Clear Day"><Trash2 size={14} /></button>
                                    <button onClick={(e) => { e.stopPropagation(); handleCopyDayToNext(d.date); }} className="p-1.5 text-slate-400 hover:text-blue-500 hover:bg-blue-50 rounded-md transition-colors" title="Copy to Next Day"><ArrowRight size={14} /></button>
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>

            {/* 5. FOOTER: SAVE & SUBMIT BAR */}
            <div className="fixed bottom-0 w-full bg-white dark:bg-[#11151F] border-t border-slate-200 dark:border-slate-800 p-4 z-40 flex justify-center items-center gap-4">
                {isLocked ? (
                    <button onClick={() => updateDb(prev => ({...prev, [currentWeekKey]: {...currentData, status: 'DRAFT'}}))} className="bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 px-8 py-3 rounded-full font-bold text-sm hover:bg-slate-300 dark:hover:bg-slate-700 transition-colors flex items-center gap-2">
                         <Lock size={16} /> Submitted - Click to Withdraw
                    </button>
                ) : (
                    <>
                        <button 
                            onClick={handleSaveDraft}
                            disabled={isSaving}
                            className={`px-8 py-3 rounded-full font-bold text-sm border flex items-center gap-2 transition-all ${hasUnsavedChanges ? 'border-amber-400 text-amber-600 bg-amber-50 animate-pulse' : 'border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                        >
                            {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                            {isSaving ? "Saving..." : "Save Draft"}
                        </button>
                        <button 
                            onClick={() => setIsSubmitModalOpen(true)} 
                            disabled={stats.total === "0.0"}
                            className="bg-blue-600 text-white px-8 py-3 rounded-full font-bold text-sm hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/30 disabled:opacity-50 disabled:shadow-none flex items-center gap-2"
                        >
                            <Check size={18} /> Submit Timesheet
                        </button>
                    </>
                )}
            </div>

            {/* --- DRAWER --- */}
            {selectedDate && (
                <div className="fixed inset-0 z-50 flex justify-end">
                    <div className="absolute inset-0 bg-slate-900/30 backdrop-blur-sm" onClick={() => setSelectedDate(null)} />
                    <div className="relative w-full max-w-md bg-white dark:bg-[#11151F] h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <div>
                                <h2 className="text-xl font-black text-slate-900 dark:text-white">
                                    {new Date(selectedDate).toLocaleDateString("en-US", { weekday: 'long' })}
                                </h2>
                                <p className="text-sm font-medium text-slate-500">{selectedDate}</p>
                            </div>
                            <button onClick={() => setSelectedDate(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full transition-colors"><X size={20} className="text-slate-500" /></button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-6">
                            <div className="space-y-4">
                                {(currentData.entries[selectedDate] || []).map((e, idx) => (
                                    <div key={e.id} className="group bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-4 shadow-sm hover:border-blue-400 transition-colors relative">
                                        <div className="flex gap-3 mb-4">
                                            <div className="flex-1">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Project</label>
                                                <select value={e.projectId} onChange={(ev) => updateEntry(selectedDate, e.id, 'projectId', ev.target.value)} className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none">
                                                    {PROJECTS.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="w-14">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Hrs</label>
                                                <input type="number" min="0" max="23" value={e.hours} onChange={(ev) => updateEntry(selectedDate, e.id, 'hours', ev.target.value)} className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none" />
                                            </div>
                                            <div className="w-14">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Mins</label>
                                                <input type="number" min="0" max="59" value={e.minutes} onChange={(ev) => updateEntry(selectedDate, e.id, 'minutes', ev.target.value)} className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none" />
                                            </div>
                                        </div>
                                        <input type="text" placeholder="Work description..." value={e.notes} onChange={(ev) => updateEntry(selectedDate, e.id, 'notes', ev.target.value)} className="w-full text-sm bg-slate-50 dark:bg-slate-800 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500/20" />
                                        <button onClick={() => deleteEntry(selectedDate, e.id)} className="absolute -top-2 -right-2 bg-white dark:bg-slate-800 text-slate-400 hover:text-red-500 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={14} /></button>
                                    </div>
                                ))}
                            </div>
                            <button onClick={() => addEntry(selectedDate)} className="w-full py-4 border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl flex items-center justify-center gap-2 text-slate-500 font-bold hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-slate-800 transition-all"><Plus size={20} /> Add Activity</button>
                        </div>
                        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900">
                             <button onClick={() => setSelectedDate(null)} className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-colors">Done</button>
                        </div>
                    </div>
                </div>
            )}

            {/* TOAST */}
            {toast && (
                <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full font-bold shadow-xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4 z-50 ${toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
                    {toast.type === 'success' ? <Check size={18} /> : <AlertTriangle size={18} />}
                    {toast.msg}
                </div>
            )}

            {/* SUBMIT MODAL */}
            {isSubmitModalOpen && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
                    <div className="bg-white dark:bg-slate-900 rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl animate-in zoom-in-95">
                        <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4"><Lock size={32} /></div>
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Confirm Submission</h3>
                        <p className="text-sm text-slate-500 mb-6">This will lock the week of <strong>{currentWeekKey}</strong>. Total: <strong>{stats.stats.total}h</strong>.</p>
                        <div className="flex gap-3 justify-center">
                            <button onClick={() => setIsSubmitModalOpen(false)} className="px-5 py-2 rounded-lg font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">Cancel</button>
                            <button onClick={handleSubmit} className="px-6 py-2 rounded-lg font-bold bg-blue-600 text-white hover:bg-blue-700">Confirm</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}